-- South Korea Transport occupation cohort.
-- Classification basis: Korean Employment Classification of Occupations (KECO) 2025.
-- Logistics Coordinator is intentionally kept as a cross-mode umbrella rather than assigned one fabricated exact code.
-- Commercial freight driving, aviation maintenance/piloting and seagoing officer roles retain their statutory qualification boundaries.

on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();

on conflict (profile_key,as_of_date) do update set shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;

on conflict (profile_key,official_code) do update set official_title=excluded.official_title,included_in_rollup=excluded.included_in_rollup,sort_order=excluded.sort_order,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at;

select p.profile_key,'job_search','Work24 job search','https://www.work24.go.kr/wk/a/b/1200/retriveDtlEmpSrchList.do','government',10,'2026-08-10' from public.country_occupation_profiles p where p.country_code='KR' and p.canonical_career_id in ('truck-driver','logistics-coordinator','aircraft-maintenance-technician','commercial-pilot','marine-engineer','deck-officer','warehouse-manager','automotive-service-technician')
on conflict (profile_key,link_type,url) do update set label=excluded.label,provider_type=excluded.provider_type,sort_order=excluded.sort_order,source_checked_at=excluded.source_checked_at;
select p.profile_key,'source','KECO 2025 classification','https://www.keis.or.kr/keis/ko/proj/114/pblc/detail.do?categoryIdx=125&pubIdx=11172','government',20,'2026-08-10' from public.country_occupation_profiles p where p.country_code='KR' and p.canonical_career_id in ('truck-driver','logistics-coordinator','aircraft-maintenance-technician','commercial-pilot','marine-engineer','deck-officer','warehouse-manager','automotive-service-technician')
on conflict (profile_key,link_type,url) do update set label=excluded.label,provider_type=excluded.provider_type,sort_order=excluded.sort_order,source_checked_at=excluded.source_checked_at;
on conflict (profile_key,link_type,url) do update set label=excluded.label,provider_type=excluded.provider_type,sort_order=excluded.sort_order,source_checked_at=excluded.source_checked_at;

select 'KR:'||canonical_career_id,source_program_key,case when relation_type='direct' then 'direct' else 'related' end,coalesce(source_checked_at,'2026-08-09'::date)
from public.program_occupation_kr_v1
where canonical_career_id in ('truck-driver','logistics-coordinator','aircraft-maintenance-technician','commercial-pilot','marine-engineer','deck-officer','warehouse-manager','automotive-service-technician')
on conflict (profile_key,program_ref) do update set relation_type=excluded.relation_type,source_checked_at=excluded.source_checked_at;
