insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('KR:truck-driver','2026-08-10',0,0,0,0,13,0,0,0,2,15,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 6223 화물차 및 특수차 운전원 is the direct truck-driving anchor.','entry_level_basis','The role is primarily a driving-licence and occupational-qualification pathway rather than a university route.','qualification_note','Business-use freight driving requires the statutory 화물운송 종사자격 in addition to the appropriate road driving licence and fitness requirements.','market_scope','Exact recurring 6223 shortage, vacancy, salary and growth evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:logistics-coordinator','2026-08-10',0,0,0,0,13,0,0,0,5,18,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','The canonical role crosses KECO 0282, 0283, 0284 and 0289 transport/inventory clerical scopes; no fabricated exact roll-up is used.','entry_level_basis','Two reviewed industrial-engineering programmes are related study pathways and operations experience is also relevant.','market_scope','Component KECO groups are not aggregated into an exact logistics-coordinator market series.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Only entry accessibility and low universal licensing burden are credited.'),'2026-08-10'),
('KR:aircraft-maintenance-technician','2026-08-10',0,0,0,0,8,0,0,0,1,9,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 8121 항공기 정비원 is the direct maintenance occupation.','entry_level_basis','Two reviewed aerospace-engineering degrees remain related academic routes rather than maintenance-licence programmes.','qualification_note','Regulated aircraft-maintenance duties require the applicable 항공정비사 aviation-personnel qualification and any relevant limitation.','market_scope','Aerospace-sector demand is not used as exact aircraft-maintenance demand.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:commercial-pilot','2026-08-10',0,0,0,0,5,0,0,0,1,6,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','Commercial Pilot is a restricted paid-flight subset of KECO 2025 6211 항공기 조종사.','entry_level_basis','The reviewed Flight Operation degree remains a related pathway; flight training, aeronautical experience and employer selection are separate gates.','qualification_note','Commercial flying requires the applicable 사업용조종사 or higher aviation-personnel qualification plus medical and operational requirements.','market_scope','General airline or aviation-sector hiring is not converted into exact Commercial Pilot market points.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:marine-engineer','2026-08-10',0,0,0,0,7,0,0,0,1,8,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','The current KSCO-to-KECO crosswalk places seagoing ship engineers within KECO 6212; CampCareer restricts this profile to 선박 기관사 duties.','entry_level_basis','One reviewed Marine System Engineering programme is a direct study link.','qualification_note','Seagoing engineer-officer duties require the applicable 기관사 해기사 면허, examination, sea service, medical fitness and required training.','market_scope','Broad KECO 6212 data is not treated as Marine Engineer-only evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:deck-officer','2026-08-10',0,0,0,0,7,0,0,0,1,8,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','Deck Officer is a restricted navigation-officer subset of KECO 2025 6212 선장 및 항해사·도선사.','entry_level_basis','One reviewed Navigation Convergence Studies programme is a direct study link.','qualification_note','Officer duties require the applicable 항해사 해기사 면허, examination, sea service, medical fitness and required training.','market_scope','Broader captain, pilot and navigation-role data is not treated as Deck Officer-only evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:warehouse-manager','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 0152 운송 관련 관리자 includes warehouse operations management; clerical warehouse work remains separate under 0284.','entry_level_basis','One reviewed Industrial Engineering programme is related, while operational and supervisory progression is a common route.','market_scope','Broad 0152 manager observations are not treated as exact Warehouse Manager evidence.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Experience-based entry and low universal licensing burden only.'),'2026-08-10'),
('KR:automotive-service-technician','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 8124 자동차 정비원 is the direct automotive-maintenance occupation.','entry_level_basis','Vocational automotive training and workplace progression provide accessible routes; one Future Automotive Engineering degree remains related study.','qualification_note','No single universal personal mechanic licence is applied across the whole canonical occupation; business and specialist inspection requirements are separate.','market_scope','Exact recurring 8124 shortage, vacancy, salary and growth evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
